    return tag_name.rsplit(":", 1)[-1]


def add_underline_to_run(run):
    """Ensure <w:rPr> exists on the run and it carries <w:u w:val="single"/>."""
    doc = run.ownerDocument
    rpr = None
    for child in run.childNodes:
        if child.nodeType == child.ELEMENT_NODE and child.tagName == "w:rPr":
            rpr = child
            break
    if rpr is None:
        rpr = doc.createElement("w:rPr")
        run.insertBefore(rpr, run.firstChild)

    # Already underlined -> make sure it is single underline.
    for child in rpr.childNodes:
        if child.nodeType == child.ELEMENT_NODE and child.tagName == "w:u":
            child.setAttribute("w:val", "single")
            return

    u_el = doc.createElement("w:u")
    u_el.setAttribute("w:val", "single")

    # Insert respecting rPr child ordering.
    children = [c for c in rpr.childNodes if c.nodeType == c.ELEMENT_NODE]
    pos = len(children)
    for i, child in enumerate(children):
        name = local(child.tagName)
        if name in RPR_ORDER:
