    chunks = []
    for t in p.getElementsByTagName("w:t"):
        chunks.append(t.firstChild.nodeValue if t.firstChild else "")
    return "".join(chunks)


def looks_like_headline(text):
    if not text:
        return False
    has_upper = any(ch.isalpha() and ch.isupper() for ch in text)
    has_lower = any(ch.isalpha() and ch.islower() for ch in text)
    return has_upper and not has_lower


