    text = paragraph_text(p).strip()
    if not text or len(text) > 80:
        return False
    if not text.isupper():
        return False
    if not any(ch.isalpha() for ch in text):
        return False
    if text[0] in "\u2022\u2013\u2014\u2500\u2501":
        return False
    return True


def set_underline(r):
    rPrs = r.getElementsByTagName("w:rPr")
    rPr = rPrs[0] if rPrs else None
    if rPr is None:
        rPr = dom.createElement("w:rPr")
        r.insertBefore(rPr, r.firstChild)

    for u in rPr.getElementsByTagName("w:u"):
        rPr.removeChild(u)

