#!/usr/bin/env python3
"""Underline all report headlines in the unpacked quarterly_report.docx OOXML.

Headlines in this report are paragraphs whose entire text is non-empty,
contains at least one ASCII letter, and is written in all capital letters
(e.g., EXECUTIVE SUMMARY, FINANCIAL HIGHLIGHTS, RISK FACTORS).  Each such
headline paragraph has every run underlined with <w:u w:val="single"/>.
"""

import re
import sys
from defusedxml import minidom

path = sys.argv[1] if len(sys.argv) > 1 else "unpacked/word/document.xml"

NS_W = "w"
letter_re = re.compile(r"[A-Za-z]")

# rPr children that are permitted to precede <w:u> in CT_RPr ordering;
# <w:u> must come after these (and before effect/bdr/shd/vertAlign/lang/etc).
BEFORE_U = {
    "rFonts", "b", "bCs", "i", "iCs", "caps", "smallCaps", "strike",
    "dstrike", "outline", "shadow", "emboss", "imprint", "noProof",
    "snapToGrid", "vanish", "webHidden", "color", "spacing", "w", "kern",
    "position", "sz", "szCs", "highlight", "u",
}


def local_name(el):
    return el.tagName.split(":")[-1]


def ensure_run_underline(run, doc):
    rpr_list = run.getElementsByTagName("w:rPr")
    if rpr_list:
        rpr = rpr_list[0]
    else:
        rpr = doc.createElement("w:rPr")
        if run.firstChild is not None:
            run.insertBefore(rpr, run.firstChild)
        else:
            run.appendChild(rpr)

    u_list = rpr.getElementsByTagName("w:u")
    if u_list:
        u_list[0].setAttribute("w:val", "single")
        return

    u = doc.createElement("w:u")
    u.setAttribute("w:val", "single")

    ref = None
    for child in rpr.childNodes:
        if child.nodeType == child.ELEMENT_NODE and local_name(child) in BEFORE_U:
            ref = child
    if ref is not None:
        rpr.insertBefore(u, ref.nextSibling)
        return

    first_elem = None
    for child in rpr.childNodes:
        if child.nodeType == child.ELEMENT_NODE:
            first_elem = child
            break
    if first_elem is not None:
        rpr.insertBefore(u, first_elem)
    else:
        rpr.appendChild(u)


def paragraph_text(p):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild is not None and t.firstChild.nodeType == t.TEXT_NODE:
            parts.append(t.firstChild.data)
    return "".join(parts)


doc = minidom.parse(path)
headline_count = 0
run_count = 0

for p in doc.getElementsByTagName("w:p"):
    text = paragraph_text(p).strip()
    if not text or not letter_re.search(text) or text != text.upper():
        continue
    runs = p.getElementsByTagName("w:r")
    if not runs:
        continue
    for run in runs:
        ensure_run_underline(run, doc)
        run_count += 1
    headline_count += 1

with open(path, "wb") as f:
    f.write(doc.toprettyxml(indent="  ", encoding="ascii"))

print("Underlined {} headline paragraphs ({} runs)".format(headline_count, run_count))

