        rpr = doc.createElement("w:rPr")
        if run.firstChild is not None:
            run.insertBefore(rpr, run.firstChild)
        else:
            run.appendChild(rpr)

    u_list = rpr.getElementsByTagName("w:u")
    if u_list:
        u_list[0].setAttribute("w:val", "single")
        return

    u = doc.createElement("w:u")
    u.setAttribute("w:val", "single")

    ref = None
    for child in rpr.childNodes:
        if child.nodeType == child.ELEMENT_NODE and local_name(child) in BEFORE_U:
            ref = child
    if ref is not None:
        rpr.insertBefore(u, ref.nextSibling)
        return

    first_elem = None
    for child in rpr.childNodes:
        if child.nodeType == child.ELEMENT_NODE:
            first_elem = child
            break
    if first_elem is not None:
        rpr.insertBefore(u, first_elem)
    else:
        rpr.appendChild(u)


def paragraph_text(p):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild is not None and t.firstChild.nodeType == t.TEXT_NODE:
            parts.append(t.firstChild.data)
    return "".join(parts)


doc = minidom.parse(path)
headline_count = 0
run_count = 0

for p in doc.getElementsByTagName("w:p"):
    text = paragraph_text(p).strip()
    if not text or not letter_re.search(text) or text != text.upper():
        continue
    runs = p.getElementsByTagName("w:r")
    if not runs:
        continue
    for run in runs:
        ensure_run_underline(run, doc)
        run_count += 1
    headline_count += 1

with open(path, "wb") as f:
    f.write(doc.toprettyxml(indent="  ", encoding="ascii"))

print("Underlined {} headline paragraphs ({} runs)".format(headline_count, run_count))
